<script>
  import {onDestroy} from 'svelte';import {client,createLoader,isAbort,fmt} from '../lib/api.js';import {draft,saveDraft} from '../lib/drafts.js';
  import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';
  export let table;export let lang='vi';
  const resource=createLoader(),key=`search:${table.slug}`,saved=draft(key,{query:'',mode:'auto',topK:3,context:null});
  let query=saved.query,mode=saved.mode,topK=saved.topK,context=saved.context,queryInput,submitted='',feedbackBusy=false,feedbackError='',feedbackSuccess='',correctId='',addEval=false,alive=true;
  $: t=(vi,en)=>lang==='en'?en:vi;
  $: result=$resource.data;
  $: top=result?.products?.[0];
  $: verdicts={matched:t('Tìm thấy kết quả phù hợp','Matching result found'),ambiguous:t('Cần thêm thông tin','More information needed'),no_match:t('Chưa tìm thấy kết quả phù hợp','No matching result'),out_of_scope:t('Câu hỏi ngoài phạm vi dữ liệu','Question outside this dataset')};
  $: samples=table.slug==='dienmay'?[t('Tủ lạnh Samsung dưới 10 triệu','Samsung refrigerator under 10 million'),t('Máy giặt cho gia đình 4 người','Washing machine for a family of four'),t('Điều hoà tiết kiệm điện','Energy-efficient air conditioner')]:table.slug==='batdongsan'?['Căn hộ 2 phòng ngủ','Nhà dưới 3 tỷ','Chung cư gần trung tâm']:['Tìm theo tên hoặc đặc điểm','Sản phẩm giá tốt','Thông tin sản phẩm'];
  async function search(){if(!query.trim())return;submitted=query.trim();feedbackError='';feedbackSuccess='';const body={text:submitted,mode,top_k:Number(topK),debug:true,...(context?{context}: {})};await resource.load(signal=>client.request(`/v1/demos/${encodeURIComponent(table.slug)}/search`,{method:'POST',body,signal,timeout:30000}));}
  function follow(){context={previous_text:submitted,previous_product_ids:[top.product_id],previous_filters:result.understanding?.filters};query='';queryInput.focus();}
  async function feedback(correct){if(feedbackBusy)return;feedbackBusy=true;feedbackError='';try{await client.mutate(`feedback:${result.request_id}`,()=>client.request(`/v1/search/${result.request_id}/feedback`,{method:'POST',body:{correct,correct_product_id:correctId?Number(correctId):null,add_to_eval:addEval}}));if(alive)feedbackSuccess=t('Đã ghi nhận phản hồi.','Feedback recorded.');}catch(e){if(alive&&!isAbort(e))feedbackError=e.message;}finally{if(alive)feedbackBusy=false;}}
  function row(product){return product.data?.raw && Object.keys(product.data.raw).length?product.data.raw:{sku:product.sku,name:product.name,price:product.price,...Object.fromEntries((product.attributes||[]).map(x=>[x.label,x.display]))};}
  onDestroy(()=>{alive=false;resource.dispose();saveDraft(key,{query,mode,topK,context});});
</script>
<section class="search-box panel">
  <div class="flex items-center gap-2 text-brand text-sm font-semibold mb-5"><Icon name="search" size={18}/>{t('Bạn muốn tìm gì?','What are you looking for?')}</div>
  <form class="flex flex-col sm:flex-row gap-3" on:submit|preventDefault={search}><label class="sr-only" for="search-query">{t('Câu hỏi tìm kiếm','Search question')}</label><input id="search-query" bind:this={queryInput} bind:value={query} maxlength="1000" required placeholder={t(`Hỏi về dữ liệu trong ${table.name}…`,`Ask a question about ${table.name}…`)} class="search-input flex-1"/><Button type="submit" variant="primary" busy={$resource.loading}><Icon name="search" size={18}/>{t('Tìm kiếm','Search')}</Button></form>
  <div class="flex flex-wrap gap-x-6 gap-y-3 mt-5"><label class="flex items-center gap-3 text-xs text-muted"><span>{t('Chế độ','Mode')}</span><select class="w-auto text-xs min-h-10" bind:value={mode}><option value="auto">{t('Tự động','Automatic')}</option><option value="fast">{t('Nhanh','Fast')}</option><option value="accurate">{t('Chính xác','Accurate')}</option></select></label><label class="flex items-center gap-3 text-xs text-muted"><span>{t('Kết quả','Results')}</span><select class="w-auto text-xs min-h-10" bind:value={topK}>{#each [1,2,3,4,5] as n}<option value={n}>{n}</option>{/each}</select></label></div>
  {#if context}<div class="flex flex-wrap gap-2 items-center bg-canvas rounded-lg mt-5 p-3 text-xs"><Icon name="clock" size={16}/>{t('Đang hỏi tiếp:','Follow-up:')} {context.previous_text}<button class="text-action ml-auto" on:click={()=>context=null}>{t('Bắt đầu lại','Start over')}</button></div>{/if}
</section>
<Notice error={$resource.error} retry={search} {lang}/>
<div aria-busy={$resource.loading} aria-live="polite" class="mt-7">
  {#if $resource.loading}<div class="panel min-h-52 flex flex-col justify-center items-center gap-4" role="status"><span class="spinner text-brand"></span><span class="text-muted">{t('Đang tìm trong dữ liệu của bạn…','Searching your data…')}</span></div>
  {:else if result}
    <section class="panel"><div class="flex items-center flex-wrap gap-3 pb-5 border-b border-line"><span class="badge" class:ok={result.status==='matched'} class:warn={result.status!=='matched'}>{verdicts[result.status]||result.status}</span>{#if result.cache_hit}<span class="badge">Cache</span>{/if}<span class="ml-auto text-xs text-muted">{fmt(Math.round(result.latency_ms?.total||0))} ms</span>{#if result.clarify_question}<p class="w-full text-sm mt-2">{result.clarify_question}</p>{/if}</div>
      {#if top}<div class="grid lg:grid-cols-[1fr_260px] gap-8 mt-6"><div><h2 class="text-xl">{top.name}</h2><p class="text-muted text-xs mt-2">{top.sku} <span class="ml-4">{t('Độ phù hợp','Match')} {Math.round(top.score*100)}%</span></p>{#if top.reason}<p class="my-4 text-muted text-sm">{top.reason}</p>{/if}<dl class="result-fields mt-5">{#each Object.entries(row(top)) as [label,value]}<dt>{label}</dt><dd>{value===null||value===undefined||value===''?'—':typeof value==='object'?JSON.stringify(value):String(value)}</dd>{/each}</dl></div><aside class="border-t lg:border-t-0 lg:border-l border-line pt-5 lg:pt-0 lg:pl-7"><h3 class="mb-4">{t('Kết quả khác','Other results')}</h3>{#each result.products.slice(1) as product}<div class="border-b border-line py-4"><p class="text-sm font-semibold">{product.name}</p><p class="text-xs text-muted mt-2">{Math.round(product.score*100)}%</p></div>{:else}<p class="text-muted text-sm">{t('Không có kết quả khác.','No other results.')}</p>{/each}</aside></div>{/if}
      {#if result.fallback_reason}<Notice error={t('Một số bước AI đã dùng phương án dự phòng: ','Some AI steps used fallback: ')+result.fallback_reason}/>{/if}
      <div class="flex flex-wrap gap-2 items-center border-t border-line mt-6 pt-5"><span class="text-xs text-muted mr-2">{t('Kết quả có đúng không?','Is this result correct?')}</span><Button busy={feedbackBusy} on:click={()=>feedback(true)}><Icon name="check" size={16}/>{t('Đúng','Yes')}</Button><Button disabled={feedbackBusy} on:click={()=>feedback(false)}>{t('Chưa đúng','No')}</Button>{#if top}<div class="sm:ml-auto"><Button on:click={follow}>{t('Hỏi tiếp','Follow up')}<Icon name="arrow" size={16}/></Button></div>{/if}</div><Notice error={feedbackError} success={feedbackSuccess}/>
      <details class="mt-4 text-sm"><summary class="text-muted cursor-pointer min-h-11">{t('Tuỳ chọn phản hồi','Feedback options')}</summary><div class="flex flex-wrap gap-4 mt-3"><label class="field"><span>{t('ID sản phẩm đúng (tuỳ chọn)','Correct product ID (optional)')}</span><input type="number" min="1" bind:value={correctId}/></label><label class="flex gap-2 items-center text-xs"><input type="checkbox" bind:checked={addEval}/>{t('Lưu vào bộ đánh giá','Add to evaluation set')}</label></div></details>
      <details class="mt-4 border-t border-line pt-4"><summary class="text-xs text-muted cursor-pointer min-h-11">{t('Chi tiết xử lý','Processing details')}</summary><div class="grid sm:grid-cols-4 gap-3 my-4">{#each ['understand','embed','retrieve','rerank'] as phase}<div class="rounded-lg bg-canvas p-3"><b>{Math.round(result.latency_ms?.[phase]||0)} ms</b><p class="text-xs text-muted">{phase}</p></div>{/each}</div><pre class="codeblock">{JSON.stringify(result,null,2)}</pre></details>
    </section>
  {:else}<section class="py-3"><h2 class="text-base mb-5">{t('Thử một câu hỏi','Try a question')}</h2><div class="grid md:grid-cols-3 gap-3">{#each samples as sample}<button class="sample" on:click={()=>{query=sample;queryInput.focus();}}><span>{sample}</span><Icon name="arrow" size={17}/></button>{/each}</div><p class="text-xs text-muted mt-6 flex gap-2 items-center"><Icon name="info" size={15}/>{t('Tìm theo tên, đặc điểm hoặc nhu cầu của bạn.','Search by name, features or what you need.')}</p></section>{/if}
</div>
<style>.search-box{border-top:3px solid #176552}.search-input{min-height:60px;font-size:16px;background:#f8faf8;border-color:#d6e3da}.sample{display:flex;align-items:center;justify-content:space-between;gap:16px;text-align:left;padding:20px;background:white;border:1px solid #dfe8e3;border-radius:10px;font-size:13px;min-height:86px}.sample:hover{border-color:#87af98;background:#fafdFA}.result-fields{display:grid;grid-template-columns:minmax(90px,35%) 1fr;gap:12px 20px;font-size:13px}.result-fields dt{color:#718477;overflow-wrap:anywhere}.result-fields dd{overflow-wrap:anywhere}</style>
